29	export async function fetchCommunityWorkspace(userId: string): Promise<CommunityWorkspace> {
30	  if (usesViewerFixtures()) {
31	    const { readFixtureState } = await loadFixtureStore();
32	    const state = readFixtureState();
33	    return {
34	      conversations: [...state.community.conversations],
35	      studyRooms: [...state.community.studyRooms],
36	      discussions: [...state.community.discussions],
