40	  }
41	
42	  const [
43	    membershipsRes,
44	    roomsRes,
45	    roomMembersRes,
46	    notesRes,
47	    discussionsRes,
48	    commentsRes,
49	    likesRes,
50	    peopleRes,
51	  ] = await Promise.all([
52	    supabase
53	      .from('community_conversation_members')
54	      .select('conversation_id, last_read_at')
55	      .eq('user_id', userId)
56	      .limit(20),
57	    supabase
58	      .from('community_study_rooms')
59	      .select('id, name, description, created_by, status')
60	      .order('created_at', { ascending: false })
61	      .limit(20),
62	    supabase
63	      .from('community_study_room_members')
64	      .select('room_id, user_id')
65	      .limit(100),
66	    supabase
67	      .from('community_notes')
68	      .select('id, title, body, room_id, lesson_id, updated_at')
69	      .eq('owner_id', userId)
70	      .order('updated_at', { ascending: false })
71	      .limit(20),
72	    supabase
73	      .from('community_discussions')
74	      .select('id, title, body, category, author_id, created_at')
75	      .order('created_at', { ascending: false })
76	      .limit(20),
77	    supabase
78	      .from('community_discussion_comments')
79	      .select('id, discussion_id, author_id, body, created_at')
80	      .order('created_at')
81	      .limit(120),
82	    supabase
83	      .from('community_discussion_likes')
84	      .select('discussion_id, user_id')
85	      .limit(200),
86	    supabase
87	      .from('profiles')
88	      .select('id, username')
89	      .neq('id', userId)
90	      .limit(12),
91	  ]);
92	
93	  for (const result of [membershipsRes, roomsRes, roomMembersRes, notesRes, discussionsRes, commentsRes, likesRes, peopleRes]) {
94	    if (result.error) {
95	      throw result.error;
96	    }
97	  }
98	
99	  const membershipRows = membershipsRes.data ?? [];
100	  const conversationIds = membershipRows.map((row) => String(row.conversation_id));
101	  const [conversationsRes, messagesRes, conversationMembersRes] = conversationIds.length
102	    ? await Promise.all([
103	        supabase
104	          .from('community_conversations')
105	          .select('id, title, kind, study_room_id, updated_at')
106	          .in('id', conversationIds)
107	          .order('updated_at', { ascending: false })
108	          .limit(20),
109	        supabase
110	          .from('community_messages')
111	          .select('id, conversation_id, author_id, body, created_at')
112	          .in('conversation_id', conversationIds)
113	          .order('created_at')
114	          .limit(120),
115	        supabase
116	          .from('community_conversation_members')
117	          .select('conversation_id, user_id')
118	          .in('conversation_id', conversationIds)
119	          .limit(120),
120	      ])
121	    : [
122	        { data: [], error: null },
123	        { data: [], error: null },
124	        { data: [], error: null },
125	      ];
126	
127	  for (const result of [conversationsRes, messagesRes, conversationMembersRes]) {
128	    if (result.error) {
129	      throw result.error;
130	    }
131	  }
132	
133	  const authorIds = new Set<string>();
134	  for (const row of messagesRes.data ?? []) {
135	    authorIds.add(String(row.author_id));
136	  }
137	  for (const row of discussionsRes.data ?? []) {
138	    authorIds.add(String(row.author_id));
139	  }
140	  for (const row of commentsRes.data ?? []) {
141	    authorIds.add(String(row.author_id));
142	  }
143	  for (const row of conversationMembersRes.data ?? []) {
144	    authorIds.add(String(row.user_id));
145	  }
146	  for (const row of roomMembersRes.data ?? []) {
147	    authorIds.add(String(row.user_id));
148	  }
149	
150	  const profileLookup = new Map<string, string>();
151	  if (authorIds.size > 0) {
152	    const { data: profiles, error: profileError } = await supabase
153	      .from('profiles')
154	      .select('id, username')
155	      .in('id', [...authorIds]);
156	    if (profileError) {
157	      throw profileError;
158	    }
159	    for (const row of profiles ?? []) {
160	      profileLookup.set(String(row.id), String(row.username ?? 'Learner'));
161	    }
162	  }
163	
164	  const conversations: CommunityConversation[] = (conversationsRes.data ?? []).map((conversation) => {
165	    const conversationId = String(conversation.id);
166	    const messages = (messagesRes.data ?? [])
167	      .filter((message) => String(message.conversation_id) === conversationId)
168	      .map((message) => ({
169	        id: String(message.id),
170	        author_id: String(message.author_id),
171	        author_name: profileLookup.get(String(message.author_id)) ?? 'Learner',
172	        body: String(message.body ?? ''),
173	        created_at: String(message.created_at ?? ''),
174	      }));
175	    const memberIds = (conversationMembersRes.data ?? [])
176	      .filter((member) => String(member.conversation_id) === conversationId)
177	      .map((member) => String(member.user_id));
178	    const membership = membershipRows.find((row) => String(row.conversation_id) === conversationId);
179	    const lastRead = membership?.last_read_at ? new Date(String(membership.last_read_at)).getTime() : 0;
180	    const unreadCount = messages.filter((message) => {
181	      if (message.author_id === userId) {
182	        return false;
183	      }
184	      return new Date(message.created_at).getTime() > lastRead;
185	    }).length;
186	    const preview = messages.at(-1)?.body ?? '';
187	    const title =
188	      String(conversation.kind) === 'direct'
189	        ? memberIds
190	            .filter((memberId) => memberId !== userId)
191	            .map((memberId) => profileLookup.get(memberId) ?? 'Learner')
192	            .join(', ') || String(conversation.title ?? 'Direct chat')
193	        : String(conversation.title ?? 'Study room');
194	    return {
195	      id: conversationId,
196	      title,
197	      kind: String(conversation.kind) === 'group' ? 'group' : 'direct',
198	      preview,
199	      participant_ids: memberIds,
200	      unread_count: unreadCount,
201	      updated_at: String(conversation.updated_at ?? messages.at(-1)?.created_at ?? ''),
202	      study_room_id: typeof conversation.study_room_id === 'string' ? conversation.study_room_id : null,
203	      messages,
204	    };
205	  });
206	
207	  const studyRooms: CommunityStudyRoom[] = (roomsRes.data ?? []).map((room) => {
208	    const memberIds = (roomMembersRes.data ?? [])
209	      .filter((member) => String(member.room_id) === String(room.id))
210	      .map((member) => String(member.user_id));
211	    const linkedConversation = (conversationsRes.data ?? []).find(
212	      (conversation) => String(conversation.study_room_id ?? '') === String(room.id),
213	    );
214	    return {
215	      id: String(room.id),
216	      name: String(room.name ?? ''),
217	      description: String(room.description ?? ''),
218	      created_by: String(room.created_by ?? ''),
219	      member_ids: memberIds,
220	      members: memberIds.length,
221	      status: String(room.status ?? 'Open now'),
222	      conversation_id: linkedConversation ? String(linkedConversation.id) : null,
223	    };
224	  });
225	
226	  const discussions: CommunityDiscussion[] = (discussionsRes.data ?? []).map((discussion) => {
227	    const discussionId = String(discussion.id);
228	    const likes = (likesRes.data ?? []).filter((like) => String(like.discussion_id) === discussionId);
229	    const comments = (commentsRes.data ?? [])
230	      .filter((comment) => String(comment.discussion_id) === discussionId)
231	      .map((comment) => ({
232	        id: String(comment.id),
233	        author_id: String(comment.author_id),
234	        author_name: profileLookup.get(String(comment.author_id)) ?? 'Learner',
235	        body: String(comment.body ?? ''),
236	        created_at: String(comment.created_at ?? ''),
237	      }));
238	    return {
239	      id: discussionId,
240	      title: String(discussion.title ?? ''),
241	      body: String(discussion.body ?? ''),
242	      category: String(discussion.category ?? 'General'),
243	      author_id: String(discussion.author_id ?? ''),
244	      author_name: profileLookup.get(String(discussion.author_id)) ?? 'Learner',
245	      created_at: String(discussion.created_at ?? ''),
246	      likes: likes.length,
247	      liked_by_me: likes.some((like) => String(like.user_id) === userId),
248	      comments,
249	    };
250	  });
251	
252	  return {
253	    conversations,
254	    studyRooms,
255	    discussions,
256	    notes: (notesRes.data ?? []).map((note) => mapCommunityNoteRow(note as Record<string, unknown>)),
257	    people: (peopleRes.data ?? []).map((person) => ({
258	      id: String(person.id),
259	      username: String(person.username ?? ''),
260	      display_name: String(person.username ?? ''),
261	      email: `${String(person.username ?? 'user')}@primoria.community`,
262	      status: 'online',
263	    })),
264	  };
265	}
