479	export async function saveCommunityNote(userId: string, note: CommunityNoteInput): Promise<CommunityNote> {
480	  const title = note.title.trim() || 'Untitled note';
481	  const body = note.body;
482	
483	  if (usesViewerFixtures()) {
484	    const { patchFixtureState } = await loadFixtureStore();
485	    const nextState = patchFixtureState((state) => {
486	      const existing = state.community.notes.find(
487	        (entry) =>
488	          entry.id === note.id ||
489	          (note.lesson_id && entry.lesson_id === note.lesson_id),
490	      );
491	      const noteId = existing?.id ?? note.id ?? `note-${Date.now()}`;
492	      const nextNote: CommunityNote = {
493	        id: noteId,
494	        title,
495	        body,
496	        room_id: note.room_id ?? null,
497	        lesson_id: note.lesson_id ?? existing?.lesson_id ?? null,
498	        updated_at: new Date().toISOString(),
499	      };
500	      const existingIndex = state.community.notes.findIndex((entry) => entry.id === noteId);
501	      if (existingIndex >= 0) {
502	        state.community.notes[existingIndex] = nextNote;
503	      } else {
504	        state.community.notes.unshift(nextNote);
505	      }
506	      return { ...state };
507	    });
508	    return nextState.community.notes.find((entry) => entry.id === (note.id ?? '')) ??
509	      nextState.community.notes.find((entry) => note.lesson_id && entry.lesson_id === note.lesson_id) ??
510	      nextState.community.notes[0]!;
511	  }
512	
513	  const payload = {
514	    owner_id: userId,
515	    title,
516	    body,
517	    room_id: note.room_id ?? null,
518	    lesson_id: note.lesson_id ?? null,
519	    updated_at: new Date().toISOString(),
520	  };
521	
522	  if (note.id) {
