        title: note.title,
        body: note.body,
        room_id: note.room_id,
        lesson_id: note.lesson_id,
      })),
    );
  }
}, [notesDraft.length, workspaceQuery.data]);
```

State shape is an array of note objects with optional `id`, required `title` and `body`, and optional `room_id` and `lesson_id`.

### 5. noteMutation Details
**Lines:** 247-259

```typescript
const noteMutation = useMutation({
  mutationFn: (note: { id?: string; title: string; body: string; room_id?: string | null; lesson_id?: string | null }) =>
    saveCommunityNote(userId, note),
  onSuccess: async () => {
    await refreshCommunity();
    setStatus({ tone: 'success', message: '笔记已保存。' });
    captureViewerEvent('viewer_community_note_saved');
  },
  onError: (error) => {
    setStatus({ tone: 'error', message: error instanceof Error ? error.message : '无法保存笔记。' });
    captureViewerError(error, { area: 'community_note_save' });
  },
});
```

Usage in JSX (line 787):
```jsx
onClick={() => noteMutation.mutate(note)}
disabled={noteMutation.isPending}
```

The mutation:
- Calls `saveCommunityNote` with current userId and note object
- Refreshes entire community workspace on success
- Sets success/error status messages
- Fires observability events for analytics
- Tracks loading state via `noteMutation.isPending`

### 6. Helper Functions for Notes

**addBlankNote (lines 279-282):**
```typescript
