            </div>
          ) : null}

          {section === 'notes' ? (
            <div className="space-y-4">
              <div className="viewer-panel flex items-center justify-between rounded-[26px] px-5 py-4">
                <div>
                  <h2 className="viewer-botanical-heading text-[2rem]">{'笔记'}</h2>
