                <div className="absolute left-1/2 top-[54%] h-[540px] w-[540px] -translate-x-1/2 -translate-y-1/2 rounded-full bg-[radial-gradient(circle,rgba(255,255,255,0.68),rgba(244,241,255,0.24)_52%,rgba(255,255,255,0)_76%)]" />
                <img
