                    />
                    <div className="mt-2 text-center text-[0.84rem] font-semibold tracking-[-0.01em] text-[#5a5670] [text-shadow:0_1px_0_rgba(255,255,255,0.78)]">
                      {person.display_name}
                    </div>
                  </div>
                );
              })}
            </div>
          ) : null}

          {section === 'study' ? (
