                  <span className="h-[17px] w-[17px] rounded-full border-2 border-white shadow-sm" style={{ background: NOTE_COLOR_MAP[activeNote.color] ?? '#b5b5b5' }} />
                </button>
                {noteColorPickerOpen && (
