                style={{ fontFamily: '"Georgia","Noto Serif SC",serif' }}
                onChange={(e) => handleNoteTitleChange(e.target.value, activeNote)}
              />
              {/* Date + tags */}
              <div className="mb-4 mt-3 flex flex-wrap items-center gap-2">
                <span className="text-[.75rem] text-[#a89d93]">
