              <span className="text-[.72rem] text-[#a89d93]">词数 <b className="font-[700] text-[#7a6b5e]">{noteStats.words}</b></span>
              <span className="text-[.72rem] text-[#a89d93]">行数 <b className="font-[700] text-[#7a6b5e]">{noteStats.lines}</b></span>
